import React from "react";

// Very small calendar-like list view that groups sessions by date.
export default function Calendar({ sessions = [] }) {
  const byDate = sessions.reduce((acc, s) => {
    const d = new Date(s.session_time).toDateString();
    if (!acc[d]) acc[d] = [];
    acc[d].push(s);
    return acc;
  }, {});

  const dates = Object.keys(byDate).sort((a, b) => new Date(a) - new Date(b));

  return (
    <div className="card">
      <h2>Calendar</h2>
      {dates.length === 0 ? (
        <p className="empty-text">No sessions scheduled.</p>
      ) : (
        dates.map((d) => (
          <div key={d} style={{ marginBottom: 12 }}>
            <h4 style={{ margin: "8px 0" }}>{d}</h4>
            <ul>
              {byDate[d].map((s) => (
                <li key={s.id} style={{ marginBottom: 6 }}>
                  <strong>{new Date(s.session_time).toLocaleTimeString()}</strong> — {s.subject || s.title} • Tutor: {s.tutorName || s.tutor_name}
                </li>
              ))}
            </ul>
          </div>
        ))
      )}
    </div>
  );
}
